'            <p>View sales reports and analytics</p>',
'        </div>',
'        <div class="bill-section">',
'            <p>Select a report from the menu</p>',
'        </div>',
'    </div>',
'',
'    <!-- Section 4: ITEMS MANAGEMENT -->',
'    <div id="items-management" class="pos-section">',
'        <div class="pos-page-header">',
unistr('            <h1>\D83C\DF54 Items Management</h1>'),
'            <p>Add, edit, or delete menu items</p>',
'        </div>',
'        <div class="bill-section">',
'            <button class="btn btn-primary" id="addItemBtn">+ Add New Item</button>',
'            <table class="bill-table" style="margin-top: 20px;">',
'                <thead>',
'                    <tr>',
'                        <th>Item Name</th>',
'                        <th>Price (PKR)</th>',
'                        <th>Category</th>',
'                        <th>Status</th>',
'                        <th>Actions</th>',
'                    </tr>',
'                </thead>',
'                <tbody id="itemsTableBody">',
'                    <tr><td colspan="5" style="text-align: center; color: #999;">Loading...</td></tr>',
'                </tbody>',
'            </table>',
'        </div>',
'    </div>',
'',
'    <!-- Section 5: SETTINGS -->',
'    <div id="settings" class="pos-section">',
'        <div class="pos-page-header">',
unistr('            <h1>\2699\FE0F Settings</h1>'),
'            <p>Configure your POS system</p>',
'        </div>',
'        <div class="bill-section">',
'            <div class="form-group">',
'                <label>Company Name</label>',
'                <input type="text" id="companyName" placeholder="Enter company name">',
'            </div>',
'            <div class="form-group">',
'                <label>Company Address</label>',
'                <input type="text" id="companyAddress" placeholder="Enter address">',
'            </div>',
'            <div class="form-group">',
'                <label>Tax Rate (%)</label>',
'                <input type="number" id="taxRate" placeholder="0" min="0" max="100" step="0.5">',
'            </div>',
'            <button class="btn btn-primary">Save Settings</button>',
'        </div>',
'    </div>',
'',
'    <!-- Section 6: HELP -->',
'    <div id="help" class="pos-section">',
'        <div class="pos-page-header">',
unistr('            <h1>\2753 Help & About</h1>'),
'            <p>Need assistance?</p>',
'        </div>',
'        <div class="bill-section">',
'            <h3 style="color: var(--nav-bg); margin-bottom: 15px;">POS System v1.0</h3>',
'            <p style="margin-bottom: 15px;">Created by: <strong>A@mir</strong></p>',
'            <p style="margin-bottom: 15px;">',
'                This POS system consists of three main database portions:',
'            </p>',
'            <ul style="margin-left: 20px; margin-bottom: 15px;">',
'                <li><strong>Portion 1:</strong> POS_ITEMS - Menu items with prices and images</li>',
'                <li><strong>Portion 2:</strong> POS_ORDERS - Order headers and transactions</li>',
'                <li><strong>Portion 3:</strong> POS_ORDER_DETAILS - Line items in each order</li>',
'            </ul>',
'            <p style="color: #666;">For more help, contact your administrator.</p>',
'        </div>',
'    </div>',
'</div>',
'',
'</body>',
'</html>'))
,p_required_patch=>wwv_flow_imp.id(5036600353299118)
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
