,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 0 AS seq_no,',
'       NULL AS order_item_id,',
'       NULL AS menu_id,',
'       NULL AS item_name,',
'       NULL AS category,',
'       NULL AS quantity,',
'       NULL AS unit_price,',
'       NULL AS item_total,',
'       NULL AS notes',
'FROM DUAL',
'WHERE 1=0',
'',
'UNION ALL',
'',
'SELECT ROWNUM,',
'       NULL,',
'       m.menu_id,',
'       m.item_name,',
'       m.category,',
'       NULL,',
'       m.price,',
'       NULL,',
