'            left: 0;',
'            right: 0;',
'            bottom: 0;',
'            background: rgba(224, 229, 236, 0.2);',
'            z-index: 0;',
'            pointer-events: none;',
'        }',
'',
'        /* Main container */',
'        .pos-container {',
'            position: relative;',
'            z-index: 1;',
'            width: 100%;',
'            max-width: 1400px;',
'            display: flex;',
'            flex-wrap: wrap;',
'            gap: 24px;',
'            justify-content: center;',
'            align-items: stretch;',
'        }',
'',
'        /* LEFT COLUMN - wider (items) */',
'        .pos-column.items-column {',
'            flex: 2 1 500px;',
'            min-width: 320px;',
'            max-width: 850px;',
'        }',
'',
'        /* RIGHT COLUMN - narrower (bill) */',
'        .pos-column.bill-column {',
'            flex: 1 1 280px;',
'            min-width: 250px;',
'            max-width: 450px;',
'        }',
'',
'        .glass-wrapper {',
'            background: rgba(224, 229, 236, 0.2);',
'            backdrop-filter: blur(6px);',
'            -webkit-backdrop-filter: blur(6px);',
'            border-radius: 48px;',
'            padding: 28px 22px;',
'            box-shadow: 0 25px 50px rgba(0, 0, 0, 0.1),',
'                        inset 0 2px 4px rgba(255, 255, 255, 0.4);',
'            border: 1px solid rgba(255, 255, 255, 0.12);',
'            height: 100%;',
'            display: flex;',
'            flex-direction: column;',
'        }',
'',
'        .col-heading {',
'            text-align: center;',
'            margin-bottom: 18px;',
'            padding-bottom: 12px;',
'            border-bottom: 2px solid rgba(255, 255, 255, 0.15);',
'        }',
'',
'        .col-heading h2 {',
'            font-size: 1.4rem;',
'            font-weight: 600;',
'            color: #1a1f2a;',
'            letter-spacing: 1px;',
'            text-shadow: 0 2px 12px rgba(255, 255, 255, 0.25);',
'        }',
'',
'        .col-heading .sub {',
'            display: block;',
'            font-size: 0.7rem;',
'            font-weight: 400;',
'            color: #2d3340;',
'            margin-top: 2px;',
'            letter-spacing: 2px;',
'            opacity: 0.7;',
'        }',
'',
'        /* Items Grid */',
'        .items-grid {',
'            display: grid;',
'            grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));',
'            gap: 16px;',
'            padding: 6px 0;',
'            flex: 1;',
'        }',
'',
'        .item-card {',
'            display: flex;',
'            flex-direction: column;',
'            align-items: center;',
'            gap: 8px;',
'            cursor: pointer;',
'            transition: transform 0.2s ease;',
'        }',
'',
'        .item-card:hover {',
'            transform: scale(1.04);',
'        }',
'',
'        .item-card:active {',
'            transform: scale(0.95);',
'        }',
'',
'        .item-card .item-label {',
'            font-size: 0.7rem;',
'            font-weight: 600;',
'            color: #1a1f2a;',
'            letter-spacing: 0.5px;',
'            text-align: center;',
'            background: rgba(224, 229, 236, 0.4);',
'            backdrop-filter: blur(4px);',
'            padding: 3px 12px;',
'            border-radius: 30px;',
'            border: 1px solid rgba(255, 255, 255, 0.15);',
'            box-shadow: inset 0 1px 3px rgba(255, 255, 255, 0.4);',
'            width: 100%;',
'            white-space: nowrap;',
'            overflow: hidden;',
'            text-overflow: ellipsis;',
'        }',
'',
'        .item-card .neumorphic {',
'            width: 100%;',
'            aspect-ratio: 1/1;',
'            max-width: 140px;',
'            border-radius: 32px;',
'            background: #e0e5ec;',
'            box-shadow: inset 10px 10px 16px #bec3c9,',
'                        inset -10px -10px 16px #ffffff,',
'                        0 4px 10px rgba(0, 0, 0, 0.02);',
'            overflow: hidden;',
'            display: flex;',
'            align-items: center;',
'            justify-content: center;',
'            transition: box-shadow 0.2s ease;',
'        }',
'',
'        .item-card .neumorphic img {',
'            width: 100%;',
'            height: 100%;',
'            object-fit: cover;',
'            display: block;',
'        }',
'',
'        .item-card:hover .neumorphic {',
'            box-shadow: inset 10px 10px 16px #bec3c9,',
'                        inset -10px -10px 16px #ffffff,',
'                        0 8px 20px rgba(0, 0, 0, 0.06);',
'        }',
'',
'        /* Bill Area */',
'        .bill-area {',
'            flex: 1;',
'            display: flex;',
'            flex-direction: column;',
'        }',
'',
'        .bill-list {',
'            flex: 1;',
'            min-height: 180px;',
'            max-height: 350px;',
'            overflow-y: auto;',
'            padding: 6px 4px;',
'            margin: 6px 0 12px 0;',
'            background: rgba(224, 229, 236, 0.15);',
'            backdrop-filter: blur(2px);',
'            border-radius: 28px;',
'            border: 1px solid rgba(255, 255, 255, 0.08);',
'        }',
'',
'        .bill-list::-webkit-scrollbar {',
'            width: 4px;',
'        }',
'        .bill-list::-webkit-scrollbar-track {',
'            background: rgba(0,0,0,0.05);',
'            border-radius: 10px;',
'        }',
'        .bill-list::-webkit-scrollbar-thumb {',
'            background: rgba(0,0,0,0.15);',
'            border-radius: 10px;',
'        }',
'',
'        .bill-item {',
'            display: flex;',
'            justify-content: space-between;',
'            align-items: center;',
'            padding: 6px 12px;',
'            margin: 3px 4px;',
'            background: rgba(224, 229, 236, 0.3);',
'            backdrop-filter: blur(4px);',
'            border-radius: 20px;',
'            border: 1px solid rgba(255, 255, 255, 0.1);',
'            font-size: 0.8rem;',
'            color: #1a1f2a;',
'            transition: background 0.2s;',
'        }',
'',
'        .bill-item:hover {',
'            background: rgba(224, 229, 236, 0.5);',
'        }',
'',
'        .bill-item .item-name {',
'            font-weight: 500;',
'            display: flex;',
'            align-items: center;',
'            gap: 8px;',
'            font-size: 0.75rem;',
'        }',
'',
'        .bill-item .item-name .thumb {',
'            width: 24px;',
'            height: 24px;',
'            border-radius: 10px;',
'            overflow: hidden;',
'            flex-shrink: 0;',
'            background: #d0d5dd;',
'        }',
'',
'        .bill-item .item-name .thumb img {',
'            width: 100%;',
'            height: 100%;',
'            object-fit: cover;',
'        }',
'',
'        .bill-item .item-actions {',
'            display: flex;',
'            align-items: center;',
'            gap: 8px;',
'        }',
'',
'        .bill-item .item-actions .item-price {',
'            font-weight: 500;',
'            font-size: 0.7rem;',
'            min-width: 45px;',
'            text-align: right;',
'        }',
'',
'        .bill-item .qty-control {',
'            display: flex;',
'            align-items: center;',
'            gap: 4px;',
'            background: rgba(224, 229, 236, 0.3);',
'            padding: 1px 6px;',
'            border-radius: 20px;',
'        }',
'',
'        .bill-item .qty-control button {',
'            background: none;',
'            border: none;',
'            font-size: 0.85rem;',
'            font-weight: 600;',
'            color: #2d3340;',
'            cursor: pointer;',
'            padding: 0 2px;',
'            width: 18px;',
'            height: 18px;',
'            border-radius: 50%;',
'            display: flex;',
'            align-items: center;',
'            justify-content: center;',
'            transition: background 0.2s;',
'        }',
'',
'        .bill-item .qty-control button:hover {',
'            background: rgba(0,0,0,0.06);',
'        }',
'',
'        .bill-item .qty-control .qty-num {',
'            min-width: 16px;',
'            text-align: center;',
'            font-weight: 600;',
'            font-size: 0.75rem;',
'        }',
'',
'        .bill-item .remove-btn {',
'            background: none;',
'            border: none;',
'            color: #8a2e2e;',
'            font-size: 0.9rem;',
'            cursor: pointer;',
'            padding: 0 2px;',
'            opacity: 0.5;',
'            transition: opacity 0.2s;',
'        }',
'',
'        .bill-item .remove-btn:hover {',
'            opacity: 1;',
'        }',
'',
'        /* Bill Total & Actions */',
'        .bill-actions {',
'            display: flex;',
'            gap: 8px;',
'            flex-wrap: wrap;',
'            margin-top: 6px;',
'        }',
'',
'        .bill-total {',
'            flex: 1;',
'            display: flex;',
'            justify-content: space-between;',
'            align-items: center;',
'            padding: 10px 16px;',
'            background: rgba(224, 229, 236, 0.3);',
'            backdrop-filter: blur(4px);',
'            border-radius: 28px;',
'            border: 1px solid rgba(255, 255, 255, 0.1);',
'            font-weight: 600;',
'            font-size: 1rem;',
'            color: #1a1f2a;',
'            min-width: 150px;',
'        }',
'',
'        .bill-total .total-price {',
'            font-size: 1.1rem;',
'            color: #1a3a2a;',
'        }',
'',
'        .action-btn {',
'            padding: 6px 14px;',
'            border-radius: 28px;',
'            font-size: 0.7rem;',
'            font-weight: 600;',
'            cursor: pointer;',
'            transition: all 0.2s ease;',
'            border: 1px solid rgba(255, 255, 255, 0.15);',
'            backdrop-filter: blur(4px);',
'            background: rgba(224, 229, 236, 0.3);',
'            color: #1a1f2a;',
'            white-space: nowrap;',
'        }',
'',
'        .action-btn:hover {',
'            transform: scale(1.02);',
'            background: rgba(224, 229, 236, 0.5);',
'        }',
'',
'        .action-btn.print-btn {',
'            background: rgba(40, 80, 140, 0.2);',
'            border-color: rgba(40, 80, 140, 0.3);',
'            color: #1a3a5a;',
'        }',
'',
'        .action-btn.print-btn:hover {',
'            background: rgba(40, 80, 140, 0.3);',
'        }',
'',
'        .action-btn.clear-btn {',
'            background: rgba(180, 60, 60, 0.15);',
'            border-color: rgba(180, 60, 60, 0.2);',
'            color: #5a2a2a;',
'        }',
'',
'        .action-btn.clear-btn:hover {',
'            background: rgba(180, 60, 60, 0.25);',
'        }',
'',
'        .empty-bill {',
'            text-align: center;',
'            color: #4a4f5a;',
'            opacity: 0.6;',
'            padding: 30px 10px;',
'            font-size: 0.8rem;',
'            letter-spacing: 1px;',
'        }',
'',
'        .footer-badge {',
'            text-align: center;',
'            margin-top: 14px;',
'        }',
'',
'        .footer-badge .badge {',
'            display: inline-block;',
'            background: rgba(224, 229, 236, 0.3);',
'            backdrop-filter: blur(4px);',
'            padding: 4px 16px;',
'            border-radius: 60px;',
'            font-size: 0.6rem;',
'            color: #1e222b;',
'            border: 1px solid rgba(255, 255, 255, 0.1);',
'            letter-spacing: 0.5px;',
'        }',
'',
'        /* Print Receipt Styles - FULL PAGE SIZE */',
'        #printReceipt {',
'            display: none;',
'        }',
'',
'        @media print {',
'            /* Hide everything except the receipt */',
'            body * {',
'                visibility: hidden;',
'            }',
'            body {',
'                background: white !important;',
'                backdrop-filter: none !important;',
'                padding: 0 !important;',
'                margin: 0 !important;',
'            }',
'            body::before {',
'                display: none !important;',
'            }',
'            ',
'            /* Show only the receipt */',
'            #printReceipt {',
'                display: block !important;',
'                position: fixed;',
'                top: 0;',
'                left: 0;',
'                width: 100%;',
'                height: 100%;',
'                background: white;',
'                z-index: 9999;',
'                visibility: visible;',
'                padding: 20px;',
'            }',
'            ',
'            #printReceipt * {',
'                visibility: visible;',
'            }',
'            ',
'            .receipt-container {',
'                max-width: 350px;',
'                margin: 0 auto;',
'                font-family: ''Courier New'', monospace;',
'                padding: 20px;',
'                font-size: 14px;',
'            }',
'            ',
'            .receipt-header {',
'                text-align: center;',
'                border-bottom: 2px dashed #333;',
'                padding-bottom: 12px;',
'                margin-bottom: 12px;',
'            }',
'            ',
'            .receipt-header h2 {',
'                margin: 0;',
'                font-size: 20px;',
'                letter-spacing: 2px;',
'            }',
'            ',
'            .receipt-header .date {',
'                font-size: 12px;',
'                color: #666;',
'                margin-top: 4px;',
'            }',
'            ',
'            .receipt-table {',
'                width: 100%;',
'                border-collapse: collapse;',
'                margin: 12px 0;',
'            }',
'            ',
'            .receipt-table th {',
'                text-align: left;',
'                padding: 6px 0;',
'                border-bottom: 1px solid #333;',
'                font-size: 13px;',
'            }',
'            ',
'            .receipt-table td {',
'                padding: 4px 0;',
'                font-size: 13px;',
'            }',
'            ',
'            .receipt-table .qty-col {',
'                text-align: center;',
'            }',
'            ',
'            .receipt-table .price-col {',
'                text-align: right;',
'            }',
'            ',
'            .receipt-total {',
'                border-top: 2px solid #333;',
'                font-weight: bold;',
'                padding-top: 8px;',
'                margin-top: 4px;',
'            }',
'            ',
'            .receipt-total td {',
'                padding: 6px 0;',
'                font-size: 15px;',
'            }',
'            ',
'            .receipt-footer {',
'                text-align: center;',
'                font-size: 11px;',
'                color: #888;',
'                border-top: 2px dashed #333;',
'                padding-top: 12px;',
'                margin-top: 12px;',
'            }',
'            ',
'            /* Ensure full page print */',
'            @page {',
'                margin: 10mm;',
'                size: auto;',
'            }',
'        }',
'',
'        /* Responsive */',
'        @media (max-width: 800px) {',
'            .pos-column.items-column,',
'            .pos-column.bill-column {',
'                flex: 1 1 100%;',
'                max-width: 100%;',
'                min-width: auto;',
'            }',
'            .items-grid {',
'                grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));',
'            }',
'            .glass-wrapper {',
'                padding: 20px 14px;',
'                border-radius: 36px;',
'            }',
'            .bill-actions {',
'                flex-direction: column;',
'            }',
'            .bill-total {',
'                min-width: auto;',
'            }',
'        }',
'',
'        @media (max-width: 450px) {',
'            .items-grid {',
'                grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));',
'                gap: 10px;',
'            }',
'            .item-card .item-label {',
'                font-size: 0.55rem;',
'                padding: 2px 6px;',
'            }',
'            .item-card .neumorphic {',
'                max-width: 100px;',
'            }',
'            .bill-item {',
'                font-size: 0.7rem;',
'                padding: 4px 8px;',
'            }',
'            .bill-total {',
'                font-size: 0.85rem;',
'                padding: 8px 12px;',
'            }',
'            .col-heading h2 {',
'                font-size: 1.1rem;',
'            }',
'            .action-btn {',
'                font-size: 0.65rem;',
'                padding: 5px 12px;',
'            }',
'        }',
'    </style>',
'</head>',
'<body>',
'',
'    <div class="pos-container">',
'',
'        <!-- LEFT COLUMN: ITEMS (wider) -->',
'        <div class="pos-column items-column">',
'            <div class="glass-wrapper">',
'                <div class="col-heading">',
unistr('                    <h2>\D83D\DCE6 Menu Items</h2>'),
'                    <span class="sub">click to add to bill</span>',
'                </div>',
'',
'                <div class="items-grid" id="itemsGrid"></div>',
'',
'                <div class="footer-badge">',
unistr('                    <div class="badge">\26A1 click item \2192 adds to bill \26A1</div>'),
'                </div>',
'            </div>',
'        </div>',
'',
'        <!-- RIGHT COLUMN: BILL (narrower) -->',
'        <div class="pos-column bill-column">',
'            <div class="glass-wrapper">',
'                <div class="col-heading">',
unistr('                    <h2>\D83E\DDFE Bill</h2>'),
'                    <span class="sub">your current order</span>',
'                </div>',
'',
'                <div class="bill-area">',
'                    <div class="bill-list" id="billList">',
unistr('                        <div class="empty-bill">\2726 no items added yet \2726</div>'),
'                    </div>',
'',
'                    <div class="bill-actions">',
'                        <div class="bill-total">',
'                            <span>Total</span>',
'                            <span class="total-price" id="totalPrice">PKR 0</span>',
'                        </div>',
unistr('                        <button class="action-btn print-btn" id="printBtn">\D83D\DDA8\FE0F Print</button>'),
unistr('                        <button class="action-btn clear-btn" id="clearBillBtn">\2715 Clear</button>'),
'                    </div>',
'                </div>',
'',
'                <div class="footer-badge">',
unistr('                    <div class="badge">\26A1 Created By <span style="font-weight:600;">A@mir</span> \26A1</div>'),
'                </div>',
'            </div>',
'        </div>',
'',
'    </div>',
'',
'    <!-- Print Receipt - Full page size with proper styling -->',
'    <div id="printReceipt">',
'        <div class="receipt-container">',
'            <div class="receipt-header">',
unistr('                <h2>\D83E\DDFE RECEIPT</h2>'),
'                <div class="date">Date: <span id="printDate"></span></div>',
'                <div style="font-size:11px; color:#888; margin-top:2px;">Order: <span id="printOrderNo"></span></div>',
'            </div>',
'            ',
'            <table class="receipt-table">',
'                <thead>',
'                    <tr>',
'                        <th>Item</th>',
'                        <th class="qty-col">Qty</th>',
'                        <th class="price-col">Price</th>',
'                    </tr>',
'                </thead>',
'                <tbody id="printBillItems"></tbody>',
'                <tfoot>',
'                    <tr class="receipt-total">',
'                        <td colspan="2">Total</td>',
'                        <td class="price-col" id="printTotal">PKR 0</td>',
'                    </tr>',
'                </tfoot>',
'            </table>',
'            ',
'            <div class="receipt-footer">',
'                Thank you for your visit!<br />',
unistr('                \2726 A@mir POS System \2726'),
'            </div>',
'        </div>',
'    </div>',
'',
'    <script>',
'        // ========================',
'        // DATA: items with names, images, and prices',
'        // ========================',
'const itemsData = [',
'    { id: 1,  name: ''Burger'',         price: 450, img: ''https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=500'' },',
'    { id: 2,  name: ''Pizza'',          price: 750, img: ''https://images.unsplash.com/photo-1574071318508-1cdbab80d002?w=500'' },',
'    { id: 3,  name: ''Pasta'',          price: 380, img: ''https://images.unsplash.com/photo-1473093295043-cdd812d0e601?w=500'' },',
'    { id: 4,  name: ''Fries'',          price: 250, img: ''https://images.unsplash.com/photo-1573080496219-bb080dd4f877?w=500'' },',
'    { id: 5,  name: ''Shake'',          price: 320, img: ''https://images.unsplash.com/photo-1579954115545-a95591f28bfc?w=500'' },',
'    { id: 6,  name: ''Salad'',          price: 280, img: ''https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=500'' },',
'    { id: 7,  name: ''Steak'',          price: 890, img: ''https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=500'' },',
'    { id: 8,  name: ''Juice'',          price: 200, img: ''https://images.unsplash.com/photo-1600271886742-f049cd451bba?w=500'' },',
'    { id: 9,  name: ''Chicken Wings'',  price: 550, img: ''https://images.unsplash.com/photo-1527477396000-e27163b481c2?w=500'' },',
'    { id: 10, name: ''Sandwich'',       price: 420, img: ''https://images.unsplash.com/photo-1553909489-cd47e0907980?w=500'' },',
'    { id: 11, name: ''Tacos'',          price: 480, img: ''https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?w=500'' },',
'    { id: 12, name: ''Donut'',          price: 180, img: ''https://images.unsplash.com/photo-1551024601-bec78aea704b?w=500'' },',
'    { id: 13, name: ''Hot Dog'',        price: 350, img: ''https://images.unsplash.com/photo-1612392062631-94dd858cba88?w=500'' },',
'    { id: 14, name: ''Fried Chicken'',  price: 650, img: ''https://images.unsplash.com/photo-1626082927389-6cd097cdc6ec?w=500'' },',
'    { id: 15, name: ''Ice Cream'',      price: 220, img: ''https://images.unsplash.com/photo-1501443762994-82bd5dace89a?w=500'' },',
'    { id: 16, name: ''Pancakes'',       price: 400, img: ''https://images.unsplash.com/photo-1528207776546-365bb710ee93?w=500'' },',
'    { id: 17, name: ''Noodles'',        price: 390, img: ''https://images.unsplash.com/photo-1569718212165-3a8278d5f624?w=500'' },',
'    { id: 18, name: ''Sushi'',          price: 950, img: ''https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=500'' },',
'    { id: 19, name: ''Cupcake'',        price: 200, img: ''https://images.unsplash.com/photo-1486427944299-d1955d23e34d?w=500'' },',
'    { id: 20, name: ''Biryani'',        price: 500, img: ''https://images.unsplash.com/photo-1585937421612-70a008356fbe?w=500'' }',
'];',
'',
'        let bill = [];',
'        let orderCounter = 0;',
'',
'        const itemsGrid = document.getElementById(''itemsGrid'');',
'        const billList = document.getElementById(''billList'');',
'        const totalPriceEl = document.getElementById(''totalPrice'');',
'        const clearBtn = document.getElementById(''clearBillBtn'');',
'        const printBtn = document.getElementById(''printBtn'');',
'',
'        // ========================',
'        // RENDER ITEMS',
'        // ========================',
'        function renderItems() {',
'            itemsGrid.innerHTML = '''';',
'            itemsData.forEach(item => {',
'                const card = document.createElement(''div'');',
'                card.className = ''item-card'';',
'                card.innerHTML = `',
'                    <div class="neumorphic">',
'                        <img src="${item.img}" alt="${item.name}" />',
'                    </div>',
unistr('                    <div class="item-label">${item.name} \00B7 PKR ${item.price}</div>'),
'                `;',
'                card.addEventListener(''click'', () => addToBill(item));',
'                itemsGrid.appendChild(card);',
'            });',
'        }',
'',
'',
'        //==============',
'        ',
'        // ========================',
'        // ADD TO BILL',
'        // ========================',
'        function addToBill(item) {',
'            const existing = bill.find(b => b.id === item.id);',
'            if (existing) {',
'                existing.qty += 1;',
'            } else {',
'                bill.push({ ...item, qty: 1 });',
'            }',
'            renderBill();',
'        }',
'',
'        // ========================',
'        // UPDATE QUANTITY',
'        // ========================',
'        function updateQty(id, delta) {',
'            const item = bill.find(b => b.id === id);',
'            if (!item) return;',
'            const newQty = item.qty + delta;',
'            if (newQty <= 0) {',
'                bill = bill.filter(b => b.id !== id);',
'            } else {',
'                item.qty = newQty;',
'            }',
'            renderBill();',
'        }',
'',
'        // ========================',
'        // REMOVE ITEM',
'        // ========================',
'        function removeItem(id) {',
'            bill = bill.filter(b => b.id !== id);',
'            renderBill();',
'        }',
'',
'        // ========================',
'        // CLEAR BILL',
'        // ========================',
'        function clearBill() {',
'            if (bill.length === 0) return;',
'            if (confirm(''Clear all items from bill?'')) {',
'                bill = [];',
'                renderBill();',
'            }',
'        }',
'',
'        // ========================',
'        // RENDER BILL',
'        // ========================',
'        function renderBill() {',
'            billList.innerHTML = '''';',
'            if (bill.length === 0) {',
unistr('                billList.innerHTML = ''<div class="empty-bill">\2726 no items added yet \2726</div>'';'),
'            } else {',
'                bill.forEach(item => {',
'                    const div = document.createElement(''div'');',
'                    div.className = ''bill-item'';',
'                    div.innerHTML = `',
'                        <div class="item-name">',
'                            <span class="thumb"><img src="${item.img}" alt="${item.name}" /></span>',
'                            ${item.name}',
'                        </div>',
'                        <div class="item-actions">',
'                            <span class="item-price">PKR ${item.price * item.qty}</span>',
'                            <div class="qty-control">',
unistr('                                <button data-id="${item.id}" data-delta="-1">\2212</button>'),
'                                <span class="qty-num">${item.qty}</span>',
'                                <button data-id="${item.id}" data-delta="1">+</button>',
'                            </div>',
unistr('                            <button class="remove-btn" data-id="${item.id}">\2715</button>'),
'                        </div>',
'                    `;',
'                    billList.appendChild(div);',
'                });',
'',
'                billList.querySelectorAll(''.qty-control button'').forEach(btn => {',
'                    btn.addEventListener(''click'', (e) => {',
'                        e.stopPropagation();',
'                        const id = parseInt(btn.dataset.id);',
'                        const delta = parseInt(btn.dataset.delta);',
'                        updateQty(id, delta);',
'                    });',
'                });',
'',
'                billList.querySelectorAll(''.remove-btn'').forEach(btn => {',
'                    btn.addEventListener(''click'', (e) => {',
'                        e.stopPropagation();',
'                        const id = parseInt(btn.dataset.id);',
'                        removeItem(id);',
'                    });',
'                });',
'            }',
'',
'            const total = bill.reduce((sum, item) => sum + (item.price * item.qty), 0);',
'            totalPriceEl.textContent = `PKR ${total}`;',
'        }',
'',
'        // ========================',
'        // PRINT FUNCTION - FULL PAGE SCALED',
'        // ========================',
'        function printReceipt() {',
'            if (bill.length === 0) {',
'                alert(''Bill is empty! Add items first.'');',
'                return;',
'            }',
'',
'            orderCounter++;',
'            const now = new Date();',
'            const dateStr = now.toLocaleDateString() + '' '' + now.toLocaleTimeString();',
'            const orderNo = ''ORD-'' + String(now.getFullYear()).slice(2) + ',
'                           String(now.getMonth()+1).padStart(2,''0'') + ',
'                           String(now.getDate()).padStart(2,''0'') + ''-'' + ',
'                           String(orderCounter).padStart(3,''0'');',
'',
'            // Build items HTML',
'            let itemsHtml = '''';',
'            bill.forEach(item => {',
'                itemsHtml += `',
'                    <tr>',
'                        <td>${item.name}</td>',
'                        <td class="qty-col">${item.qty}</td>',
'                        <td class="price-col">PKR ${item.price * item.qty}</td>',
'                    </tr>',
'                `;',
'            });',
'',
'            const total = bill.reduce((sum, item) => sum + (item.price * item.qty), 0);',
'',
'            // Update print receipt content',
'            document.getElementById(''printDate'').textContent = dateStr;',
'            document.getElementById(''printOrderNo'').textContent = orderNo;',
'            document.getElementById(''printBillItems'').innerHTML = itemsHtml;',
'            document.getElementById(''printTotal'').textContent = ''PKR '' + total;',
'',
'            // Use window.print() - the @media print will handle showing the receipt',
'            window.print();',
'        }',
'',
'        // ========================',
'        // EVENT LISTENERS',
'        // ========================',
'        clearBtn.addEventListener(''click'', clearBill);',
'        printBtn.addEventListener(''click'', printReceipt);',
'',
'        // ========================',
'        // INIT',
'        // ========================',
'        renderItems();',
'        renderBill();',
'    </script>',
'',
'</body>',
'</html>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20260822094928Z')
,p_updated_on=>wwv_flow_imp.dz('20260822095433Z')
,p_created_by=>'AMIR'
,p_updated_by=>'AMIR'
);
end;
/
